/**
 * The contract both `input.tsx` (native) and `input.web.tsx` implement.
 *
 * It lives in its own module because Metro resolves `./input` to `input.web.tsx`
 * on web — the web file importing the shared pieces from `./input` would be
 * importing itself.
 */

import type { Ref } from "react";

/**
 * Everything but `text`, `number`, `password` and the four keyboard types falls back to plain text
 * entry off web.
 *
 * `password` is here because it is the one non-web type native implements properly:
 * `secureTextEntry` masks the field and tells the platform keyboard to leave it out of
 * autocorrect and the suggestion strip. `email`, `search`, `url` and `tel` raise the matching
 * keyboard on device — they are `inputMode`s there and real input types on web. `time`,
 * `datetime-local`, `date` and `color` are real DOM controls with no native counterpart, and
 * degrade to a text box.
 *
 * The web half takes every DOM input type on top of these (`input.web.tsx`), so a shadcn call site
 * with `type="checkbox"` or `type="file"` still compiles there; this list is the part that means
 * something on both platforms.
 */
export type InputType =
  | "text"
  | "number"
  | "password"
  | "email"
  | "search"
  | "url"
  | "tel"
  | "time"
  | "date"
  | "datetime-local"
  | "color";

/** The keyboard each type raises on native when the caller has not chosen one with `inputMode`. */
export const NATIVE_INPUT_MODE: Partial<Record<InputType, NonNullable<InputProps["inputMode"]>>> = {
  number: "numeric",
  email: "email",
  search: "search",
  url: "url",
  tel: "tel",
};

/**
 * What a caller may do to an input imperatively. `select` is web-only —
 * `TextInput` has no equivalent — so callers must treat it as optional.
 *
 * On web the ref is the `<input>` itself rather than an object built to this shape: an
 * `HTMLInputElement` already has both methods, so a `Ref<InputHandle>` is served by it, and a
 * shadcn call site holding a `useRef<HTMLInputElement>` gets the element it asked for.
 */
export type InputHandle = {
  focus: () => void;
  select?: () => void;
};

export type InputProps = {
  value?: string | undefined;
  /** Uncontrolled: where the text starts, when nothing above is holding `value`. */
  defaultValue?: string | undefined;
  onChangeText?: ((text: string) => void) | undefined;
  onBlur?: (() => void) | undefined;
  /** Enter on web, the return key on native. */
  onSubmitEditing?: (() => void) | undefined;
  placeholder?: string | undefined;
  type?: InputType | undefined;
  /**
   * Which keyboard to raise. Not the same knob as `type`: `type="number"` is what
   * gets the DOM spinners and the browser's numeric parsing, `inputMode="decimal"`
   * is what gets a phone keypad, and a number field wants both.
   */
  inputMode?: "text" | "decimal" | "numeric" | "tel" | "search" | "email" | "url" | undefined;
  maxLength?: number | undefined;
  /** Web only; the native keyboard has no equivalent constraint. */
  min?: number | undefined;
  max?: number | undefined;
  disabled?: boolean | undefined;
  className?: string | undefined;
  /**
   * Ties the control to its `<label>` on the web. React Native takes `id` as its `nativeID`, so on
   * device it is only a target for another element's `aria-labelledby`.
   */
  id?: string | undefined;
  /**
   * The accessible name, for an input no `<label>` points at — the time box beside
   * a date trigger. `TextInput` takes it on device, and react-native-web renders it.
   */
  "aria-label"?: string | undefined;
  /**
   * The accessible name by reference. The web honours a list of ids; Android reads one, and iOS
   * none, so a native caller that needs the name everywhere passes `aria-label` too.
   */
  "aria-labelledby"?: string | undefined;
  autoFocus?: boolean | undefined;
  ref?: Ref<InputHandle> | undefined;
};

export const INPUT_CLASS =
  "border-input bg-background text-foreground ring-offset-background placeholder:text-muted-foreground focus-visible:ring-ring flex h-10 w-full rounded-md border px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2";

/**
 * Copied from `registry/ui/input.web.tsx` by `scripts/rn2web`.
 * Do not edit — edit the source and re-run `npm run compile`.
 *
 * This is level 4 of the plan: the item has a hand-written web half, so nothing was generated. The
 * same passes still ran over it, and for a file already written against the DOM they find nothing
 * to do beyond pointing its sibling imports at the web tree. That is deliberate — running one
 * pipeline over the whole output tree is what guarantees a hand-written half and a compiled one
 * speak the same prop vocabulary, instead of the two drifting where nobody is looking.
 */

/**
 * The web implementation — see `input.tsx` for why this one is split, and
 * `input-base.ts` for the contract both sides implement.
 *
 * It keeps the DOM `<input>` so `type="time"`, `type="number"` and `min`/`max`
 * keep working, and adapts the event to the shared `onChangeText` contract so
 * no call site has to know which platform it is on.
 *
 * **It is also shadcn's `Input`, prop for prop.** This file installs at the
 * same `components/ui/input.tsx` a DOM app's shadcn primitive lives at, so the
 * first `shadcn add @cubeui/…` overwrites that primitive — and every
 * `<Input onChange={(e) => …}>`, `name`, `defaultValue`, `onKeyDown`, every DOM
 * input `type` and every `useRef<HTMLInputElement>` already in the app has to
 * keep compiling and keep working. So the props are the shared contract on top
 * of `ComponentProps<"input">`, both change handlers fire, and the ref is the
 * element (which already satisfies `InputHandle`, so shared call sites holding
 * one are served by the same object).
 */

import type { ComponentPropsWithoutRef, HTMLInputTypeAttribute, Ref } from "react";
import {
  INPUT_CLASS,
  type InputHandle,
  type InputType,
  type InputProps as SharedInputProps,
} from "@/components/ui/input-base";
import { cn } from "@/lib/utils";

/**
 * The shared contract, widened to everything a DOM `<input>` takes.
 *
 * `onBlur`, `min`/`max`, `value` and `defaultValue` take the DOM's wider types — a `() => void` is
 * still one, and a `string` is still a `string | number | readonly string[]` — and `type` is every
 * DOM input type, of which `InputType` is the cross-platform part.
 */
export type InputProps = Omit<ComponentPropsWithoutRef<"input">, "type" | "className"> &
  Omit<
    SharedInputProps,
    "type" | "ref" | "onBlur" | "min" | "max" | "inputMode" | "value" | "defaultValue"
  > & {
    type?: HTMLInputTypeAttribute | undefined;
    ref?: Ref<HTMLInputElement> | Ref<InputHandle> | undefined;
  };

function Input({
  className,
  type = "text",
  onChange,
  onChangeText,
  onKeyDown,
  onSubmitEditing,
  ref,
  ...props
}: InputProps) {
  return (
    <input
      // The element is the handle: it has `focus` and `select`, which is all `InputHandle` asks.
      ref={ref as Ref<HTMLInputElement>}
      data-slot="input"
      type={type}
      onChange={(e) => {
        onChange?.(e);
        onChangeText?.(e.target.value);
      }}
      onKeyDown={(e) => {
        onKeyDown?.(e);
        if (e.key === "Enter" && onSubmitEditing && !e.defaultPrevented) {
          e.preventDefault();
          onSubmitEditing();
        }
      }}
      {...props}
      className={cn(
        INPUT_CLASS,
        "file:border-0 file:bg-transparent file:text-sm file:font-medium disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive",
        className,
      )}
    />
  );
}

export type { InputHandle, InputType };
export { Input };
